#!/usr/bin/env bash
# this_file: build.sh
#
# Build fontlab-python-pens sdist + wheel into dist/. hatch-vcs takes the version from
# the vX.Y.Z git tag on HEAD. A dirty tree or an untagged HEAD would give a
# .devN+g<sha> version that PyPI rejects, so this refuses to build one unless
# ALLOW_DEV=1. Make a release tag with ./release.sh. An optional build.post.sh
# runs after the build (for repo-specific extras). Generated by pypitrust.

set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

TAG="$(git describe --tags --exact-match --match 'v[0-9]*.[0-9]*.[0-9]*' HEAD 2>/dev/null || true)"
DIRTY="$(git status --porcelain --untracked-files=no)"
if [[ "${ALLOW_DEV:-0}" != 1 ]]; then
  if [[ -n "$DIRTY" ]]; then
    echo "error: tracked files have uncommitted changes; commit them or run ./release.sh" >&2
    printf '%s\n' "$DIRTY" >&2
    exit 1
  fi
  if [[ ! "$TAG" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
    echo "error: HEAD has no vX.Y.Z tag; run ./release.sh (or ALLOW_DEV=1 ./build.sh)" >&2
    exit 1
  fi
fi

rm -rf dist
uv build --out-dir dist

if [[ "${ALLOW_DEV:-0}" != 1 ]]; then
  VER="${TAG#v}"
  for f in dist/*.whl dist/*.tar.gz; do
    case "$(basename "$f")" in
      *-"$VER"-*.whl | *-"$VER".tar.gz) ;;
      *) echo "error: $f does not carry version $VER" >&2; exit 1 ;;
    esac
  done
fi

if [[ -f build.post.sh ]]; then bash build.post.sh; fi
ls -l dist
